import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.DHtetOlu.js";const m=JSON.parse('{"title":"Solving","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/solver.md","filePath":"en/guide/solver.md"}'),n={name:"en/guide/solver.md"};function i(o,e,c,l,h,d){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="solving" tabindex="-1">Solving <a class="header-anchor" href="#solving" aria-label="Permalink to &quot;Solving&quot;">​</a></h1><p>The problem physics lives under <strong>Solver</strong>. The <strong>Magnetic field</strong> node is created with the project; the <code>+</code> next to <strong>Model</strong> creates other physics, such as an <strong>external circuit</strong>. The ▶ button solves (generating the mesh first if needed), and messages explain what is missing: a region without a material, no boundary with a prescribed A, an invalid B-H curve…</p><h2 id="analysis-types" tabindex="-1">Analysis types <a class="header-anchor" href="#analysis-types" aria-label="Permalink to &quot;Analysis types&quot;">​</a></h2><p>In the physics properties, choose the <strong>analysis</strong>:</p><table tabindex="0"><thead><tr><th>Analysis</th><th>What it solves</th><th>Parameters</th></tr></thead><tbody><tr><td>Magnetostatic</td><td>fields from DC currents and magnets</td><td>—</td></tr><tr><td>Harmonic (AC)</td><td>sinusoidal steady state, with phasors</td><td>frequency (Hz)</td></tr><tr><td>Transient</td><td>time evolution, with eddy currents</td><td>time step Δt and end time</td></tr></tbody></table><h3 id="magnetostatic" tabindex="-1">Magnetostatic <a class="header-anchor" href="#magnetostatic" aria-label="Permalink to &quot;Magnetostatic&quot;">​</a></h3><p>Solves −∇·(ν∇A) = J (plus the magnet term) with A_z in planar problems or ψ = r·A_φ in axisymmetric ones. If any material has a B-H curve, the problem is <strong>nonlinear</strong> and solved by <strong>Newton-Raphson</strong> with a line search; the number of iterations is shown with the results.</p><h3 id="harmonic-ac" tabindex="-1">Harmonic (AC) <a class="header-anchor" href="#harmonic-ac" aria-label="Permalink to &quot;Harmonic (AC)&quot;">​</a></h3><p>Currents are <strong>peak amplitudes</strong> at the given frequency. Conductors with σ &gt; 0 and no source carry <strong>eddy currents</strong>. Materials with a B-H curve use the effective permeability (as in FEMM), iterated until it converges. Results can be viewed over one period, A(t) = Re(Â e^{jωt}), and surface integrals give <strong>eddy-current losses</strong> and <strong>iron losses</strong> (Steinmetz, with the material coefficients).</p><h3 id="transient" tabindex="-1">Transient <a class="header-anchor" href="#transient" aria-label="Permalink to &quot;Transient&quot;">​</a></h3><p>Implicit Euler with time step Δt up to the end time. Currents can be <strong>functions of t</strong>, for example <code>10*sin(2*pi*60*t)</code> or <code>5*min(1, t/0.002)</code> (a 2 ms ramp up to 5 A); conductors without a source carry eddy currents; steel is nonlinear at every step. In the results, the view gets a <strong>time bar</strong> and table items become <strong>curves over time</strong>.</p><h2 id="external-circuit" tabindex="-1">External circuit <a class="header-anchor" href="#external-circuit" aria-label="Permalink to &quot;External circuit&quot;">​</a></h2><p>With the <strong>Circuit</strong> physics, coils of the model join a schematic with sources, resistors, inductors and capacitors, solved <strong>together with the field</strong> (strong coupling). See <a href="./circuit.html">External circuit</a>.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><p>The solver runs in a Web Worker, in WebAssembly, without freezing the interface. Problems with tens of thousands of elements solve in seconds in linear magnetostatics. The matrix is sparse, solved by LDLᵀ (static) or LU (AC and circuit). See the <a href="./../theory/formulation.html">formulation</a> for details.</p>',15)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
